<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
Auth::requireLogin();
Auth::ensureUserSchema();
$pdo=Database::connection();ensure_member_soft_delete_schema($pdo);ensure_member_type_schema($pdo);
$message='';$error='';
function role_label(string $role):string{return ['member'=>'Lid','admin'=>'Administrator','superadmin'=>'SuperAdmin'][$role]??$role;}
function load_user(PDO $pdo,int $id):array|false{$s=$pdo->prepare('SELECT * FROM users WHERE id=:id');$s->execute(['id'=>$id]);return $s->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='create'){
   $name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$role=(string)($_POST['role']??'member');$memberId=(int)($_POST['member_id']??0);
   if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Naam en geldig e-mailadres zijn verplicht.');
   if(strlen($password)<10)throw new RuntimeException('Het tijdelijke wachtwoord moet minstens 10 tekens bevatten.');
   if(!in_array($role,['member','admin','superadmin'],true))throw new RuntimeException('Ongeldige rol.');
   if($role!=='member'&&!Auth::isSuperAdmin())throw new RuntimeException('Alleen een SuperAdmin kan beheerdersaccounts toevoegen.');
   if($role==='member'&&$memberId<=0)throw new RuntimeException('Koppel een ledenaccount aan een lid.');
   if($role!=='member')$memberId=0;
   $pdo->prepare('INSERT INTO users(member_id,name,email,password_hash,role,is_active) VALUES(:member,:name,:email,:hash,:role,1)')->execute(['member'=>$memberId?:null,'name'=>$name,'email'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);
   if($memberId){$pdo->prepare('UPDATE members SET email=:e WHERE id=:id AND (email IS NULL OR email="")')->execute(['e'=>$email,'id'=>$memberId]);}
   $message='Gebruikersaccount aangemaakt.';
  }elseif($action==='toggle'){
   $id=(int)($_POST['id']??0);$u=load_user($pdo,$id);if(!$u)throw new RuntimeException('Account niet gevonden.');
   if(in_array($u['role'],['admin','superadmin'],true)&&!Auth::isSuperAdmin())throw new RuntimeException('Alleen een SuperAdmin kan beheerdersaccounts wijzigen.');
   if($id===(int)($_SESSION['user_id']??0))throw new RuntimeException('Je kunt je eigen account hier niet deactiveren.');
   $pdo->prepare('UPDATE users SET is_active=1-is_active WHERE id=:id')->execute(['id'=>$id]);$message='Accountstatus aangepast.';
  }elseif($action==='role'){
   if(!Auth::isSuperAdmin())throw new RuntimeException('Alleen een SuperAdmin kan rollen wijzigen.');
   $id=(int)($_POST['id']??0);$role=(string)($_POST['role']??'');$u=load_user($pdo,$id);if(!$u)throw new RuntimeException('Account niet gevonden.');
   if(!in_array($role,['member','admin','superadmin'],true))throw new RuntimeException('Ongeldige rol.');
   if($id===(int)($_SESSION['user_id']??0)&&$role!=='superadmin')throw new RuntimeException('Je kunt je eigen SuperAdmin-rechten niet via dit scherm verlagen.');
   if($role==='member'&&empty($u['member_id']))throw new RuntimeException('Een ledenrol vereist een gekoppelde ledenfiche.');
   if($role!=='member')$pdo->prepare('UPDATE users SET role=:r,member_id=NULL WHERE id=:id')->execute(['r'=>$role,'id'=>$id]);else $pdo->prepare('UPDATE users SET role=:r WHERE id=:id')->execute(['r'=>$role,'id'=>$id]);
   $message='Rol aangepast.';
  }elseif($action==='password'){
   $id=(int)($_POST['id']??0);$password=(string)($_POST['new_password']??'');$u=load_user($pdo,$id);if(!$u)throw new RuntimeException('Account niet gevonden.');
   if(in_array($u['role'],['admin','superadmin'],true)&&!Auth::isSuperAdmin())throw new RuntimeException('Alleen een SuperAdmin kan het wachtwoord van een beheerder resetten.');
   if(strlen($password)<10)throw new RuntimeException('Het nieuwe wachtwoord moet minstens 10 tekens bevatten.');
   $pdo->prepare('UPDATE users SET password_hash=:h WHERE id=:id')->execute(['h'=>password_hash($password,PASSWORD_DEFAULT),'id'=>$id]);$message='Wachtwoord opnieuw ingesteld.';
  }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$users=$pdo->query('SELECT u.*,m.member_number,m.first_name,m.last_name FROM users u LEFT JOIN members m ON m.id=u.member_id ORDER BY FIELD(u.role,"superadmin","admin","member"),u.name')->fetchAll();
$members=$pdo->query('SELECT m.id,m.member_number,m.first_name,m.last_name,m.email FROM members m LEFT JOIN users u ON u.member_id=m.id WHERE m.deleted_at IS NULL AND u.id IS NULL ORDER BY m.last_name,m.first_name')->fetchAll();
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gebruikersbeheer | Heli One</title><style>body{font-family:Arial,sans-serif;background:#f5f6f8;margin:0;color:#171717}header{background:#111;color:#fff;padding:18px 28px;display:flex;justify-content:space-between}header a{color:#fff}main{max-width:1250px;margin:32px auto;padding:0 22px}.card,.tablewrap{background:#fff;border-radius:14px;box-shadow:0 4px 18px #0000000d;margin:18px 0}.card{padding:22px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.full{grid-column:1/-1}label{display:block;font-weight:700;font-size:14px;margin-bottom:6px}input,select{width:100%;box-sizing:border-box;padding:10px;border:1px solid #d4d9df;border-radius:8px;font:inherit}.btn{padding:9px 13px;border:0;border-radius:8px;background:#111;color:#fff;text-decoration:none;cursor:pointer;font-weight:700}.secondary{background:#e7eaee;color:#111}.danger{background:#981b1b}.ok,.err{padding:12px 14px;border-radius:9px}.ok{background:#e9f8ee}.err{background:#feecec}.muted{color:#68707a}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:1000px}th,td{padding:12px 13px;border-bottom:1px solid #eceff2;text-align:left;vertical-align:middle}th{background:#fafbfc;font-size:13px;color:#68707a}.pill{padding:5px 8px;border-radius:999px;background:#eef1f4;font-size:12px}.actions{display:flex;gap:7px;flex-wrap:wrap}.inline{display:flex;gap:6px;align-items:center}.inline input,.inline select{width:auto;min-width:130px}.pw-wrap{position:relative}.pw-wrap input{padding-right:46px}.pw-toggle{position:absolute;right:5px;top:50%;transform:translateY(-50%);width:36px;height:34px;border:0;background:transparent;border-radius:7px;cursor:pointer;font-size:18px;line-height:1;color:#555;display:grid;place-items:center}.pw-toggle:hover{background:#eef1f4}.inline .pw-wrap{min-width:190px}.inline .pw-wrap input{width:100%;min-width:190px}@media(max-width:700px){.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body><header><strong>Heli One Members</strong><div><a href="/">Dashboard</a></div></header><main><h1>Gebruikersbeheer</h1><p class="muted">Ledenaccounts kunnen door Admin en SuperAdmin worden beheerd. Beheerdersrollen alleen door SuperAdmin.</p><?php if($message):?><p class="ok"><?=e($message)?></p><?php endif;?><?php if($error):?><p class="err"><?=e($error)?></p><?php endif;?><section class="card"><h2>Account toevoegen</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="grid"><div><label>Naam</label><input name="name" required></div><div><label>E-mail</label><input type="email" name="email" required></div><div><label>Tijdelijk wachtwoord</label><div class="pw-wrap"><input type="password" name="password" minlength="10" required><button class="pw-toggle" type="button" aria-label="Wachtwoord tonen" title="Wachtwoord tonen">👁</button></div></div><div><label>Rol</label><select name="role" id="role"><option value="member">Lid</option><?php if(Auth::isSuperAdmin()):?><option value="admin">Administrator</option><option value="superadmin">SuperAdmin</option><?php endif;?></select></div><div class="full" id="memberLink"><label>Koppel aan lid</label><select name="member_id"><option value="0">Kies een lid...</option><?php foreach($members as$m):?><option value="<?=(int)$m['id']?>"><?=e($m['last_name'].' '.$m['first_name'].' · '.($m['member_number']??''))?></option><?php endforeach;?></select></div></div><p><button class="btn" type="submit">Account aanmaken</button></p></form></section><div class="tablewrap"><table><thead><tr><th>Gebruiker</th><th>Rol</th><th>Gekoppeld lid</th><th>Status</th><th>Laatste login</th><th>Acties</th></tr></thead><tbody><?php foreach($users as$u):?><tr><td><strong><?=e($u['name'])?></strong><br><span class="muted"><?=e($u['email'])?></span></td><td><span class="pill"><?=e(role_label($u['role']))?></span></td><td><?=!empty($u['member_id'])?e(($u['last_name']??'').' '.($u['first_name']??'').' · '.($u['member_number']??'')):'—'?></td><td><?=$u['is_active']?'Actief':'Inactief'?></td><td><?=e($u['last_login_at']??'—')?></td><td><div class="actions"><?php $canManage=($u['role']==='member'||Auth::isSuperAdmin());if($canManage&&$u['id']!==(int)($_SESSION['user_id']??0)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><button class="btn secondary"><?=$u['is_active']?'Deactiveren':'Activeren'?></button></form><?php endif;?><?php if(Auth::isSuperAdmin()):?><form method="post" class="inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="role"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><select name="role"><option value="member" <?=$u['role']==='member'?'selected':''?>>Lid</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Administrator</option><option value="superadmin" <?=$u['role']==='superadmin'?'selected':''?>>SuperAdmin</option></select><button class="btn secondary">Rol opslaan</button></form><?php endif;?><form method="post" class="inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="password"><input type="hidden" name="id" value="<?=(int)$u['id']?>"><div class="pw-wrap"><input type="password" name="new_password" minlength="10" placeholder="Nieuw wachtwoord" required><button class="pw-toggle" type="button" aria-label="Wachtwoord tonen" title="Wachtwoord tonen">👁</button></div><button class="btn secondary">Reset</button></form></div></td></tr><?php endforeach;?></tbody></table></div></main><script>const role=document.getElementById('role'),box=document.getElementById('memberLink');function sync(){box.style.display=role.value==='member'?'block':'none'}role.addEventListener('change',sync);sync();document.querySelectorAll('.pw-toggle').forEach(btn=>btn.addEventListener('click',()=>{const input=btn.closest('.pw-wrap').querySelector('input');const show=input.type==='password';input.type=show?'text':'password';btn.textContent=show?'🙈':'👁';btn.setAttribute('aria-label',show?'Wachtwoord verbergen':'Wachtwoord tonen');btn.title=show?'Wachtwoord verbergen':'Wachtwoord tonen';}));</script></body></html>